// Temporary probe: replay a string of D moves through the real game logic
// and report when pieces lock and when (if ever) the game ends.
import { getLogic } from './src/components/Game/logic.ts'
import hatetrisRotationSystem from './src/rotation-systems/hatetris-rotation-system.ts'
import { hatetrisAi } from './src/enemy-ais/hatetris-ai.ts'
import hatetrisReplayCodec from './src/replay-codecs/hatetris-replay-codec.ts'

const wellDepth = 20
const wellWidth = 10
const bar = 4

const logic = getLogic({
  bar,
  replayTimeout: 0,
  copyTimeout: 100,
  rotationSystem: hatetrisRotationSystem,
  wellDepth,
  wellWidth
})

const enemy = { shortDescription: 'x', buttonDescription: 'x', ai: hatetrisAi }

let state = {
  error: null,
  displayEnemy: false,
  enemy,
  customAiCode: '',
  mode: 'REPLAYING',
  wellStateId: -1,
  wellStates: [],
  replay: [],
  replayCopiedTimeoutId: undefined,
  replayTimeoutId: undefined
}

const firstWellState = await logic.getFirstWellState(state)
state = { ...state, wellStateId: 0, wellStates: [firstWellState] }

const replay = hatetrisReplayCodec.decode(process.argv[2] ?? 'D')
state = { ...state, replay }
console.log('replay length:', replay.length)

for (let i = 0; i < replay.length; i++) {
  const prevPiece = state.wellStates[state.wellStateId].piece
  state = await logic.handleMove(state, replay[i])
  const ws = state.wellStates[state.wellStateId]
  const locked = prevPiece !== null && ws.piece === null
  const spawned = ws.piece !== null
  if (locked || state.mode === 'GAME_OVER') {
    console.log(`step ${i + 1}: locked, mode=${state.mode}, score=${ws.core.score}`)
    if (state.mode === 'GAME_OVER') {
      break
    }
  }
}

console.log('final mode:', state.mode, 'wellStateId:', state.wellStateId, 'replay len:', state.replay.length)
console.log('next step in replay?', state.wellStateId + 1 in state.replay)
console.log('well (bottom 8 rows):', state.wellStates[state.wellStateId].core.well.slice(-8).map(r => (r ? r.toString(2).padStart(wellWidth, '0') : r.toString(2).padStart(wellWidth, '0'))).join('\n'))

