// Temporary probe: is this.state fresh after `await`-ing an async method
// that calls this.setState inside a setTimeout callback, in React 19?
import * as React from 'react'
import * as ReactDOM from 'react-dom/client'

const container = document.createElement('div')
document.body.appendChild(container)

let log = []

class P extends React.Component {
  constructor (props) {
    super(props)
    this.state = { x: 0 }
  }

  kick = async () => {
    log.push('kick: state.x=' + this.state.x)
    await this.mutate()
    log.push('after await: state.x=' + this.state.x)
  }

  mutate = async () => {
    const v = await Promise.resolve(1)
    this.setState({ x: v })
    return v
  }
}

const root = ReactDOM.createRoot(container)
root.render(React.createElement(P))

const inst = root._internalRoot.current Fiber?.stateNode
// fallback: find via ref
console.log('probe: checking state freshness after await in setTimeout')
setTimeout(async () => {
  // simulate: trigger kick via a global
  const el = container
  // access the instance through a ref-less trick: re-render not needed;
  // use the component instance captured below
}, 0)

// Simpler: drive it manually
let instance
const ref = React.createRef()
class P2 extends React.Component {
  constructor (props) {
    super(props)
    this.state = { x: 0 }
  }
  mutate = async () => {
    const v = await Promise.resolve(1)
    this.setState({ x: v })
    return v
  }
  async go () {
    log.push('before: x=' + this.state.x)
    await this.mutate()
    log.push('after-await-microtask: x=' + this.state.x)
  }
  componentDidMount () {
    instance = this
  }
}
root.unmount()
const root2 = ReactDOM.createRoot(container)
root2.render(React.createElement(P2, { ref }))

await new Promise(r => setTimeout(r, 50))
await instance.go()
log.push('end-of-microtasks: x=' + instance.state.x)
await new Promise(r => setTimeout(r, 50))
log.push('after-50ms-macrotask: x=' + instance.state.x)
console.log(log.join('\n'))

